// --- lib_ams.FDb.ind_proc.InsertMaybe
// Insert row into hash table. Return true if row is reachable through the hash after the function completes.
bool lib_ams::ind_proc_InsertMaybe(lib_ams::FProc& row) {
    bool retval = true; // if already in hash, InsertMaybe returns true
    if (LIKELY(row.ind_proc_next == (lib_ams::FProc*)-1)) {// check if in hash already
        row.ind_proc_hashval = ams::ProcId_Hash(0, row.proc_id);
        ind_proc_Reserve(1);
        u32 index = row.ind_proc_hashval & (_db.ind_proc_buckets_n - 1);
        lib_ams::FProc* *prev = &_db.ind_proc_buckets_elems[index];
        do {
            lib_ams::FProc* ret = *prev;
            if (!ret) { // exit condition 1: reached the end of the list
                break;
            }
            if ((*ret).proc_id == row.proc_id) { // exit condition 2: found matching key
                retval = false;
                break;
            }
            prev = &ret->ind_proc_next;
        } while (true);
        if (retval) {
            row.ind_proc_next = *prev;
            _db.ind_proc_n++;
            *prev = &row;
        }
    }
    return retval;
}

// --- lib_ams.FDb.ind_proc.Remove
// Remove reference to element from hash index. If element is not in hash, do nothing
void lib_ams::ind_proc_Remove(lib_ams::FProc& row) {
    if (LIKELY(row.ind_proc_next != (lib_ams::FProc*)-1)) {// check if in hash already
        u32 index = row.ind_proc_hashval & (_db.ind_proc_buckets_n - 1);
        lib_ams::FProc* *prev = &_db.ind_proc_buckets_elems[index]; // addr of pointer to current element
        while (lib_ams::FProc *next = *prev) {                          // scan the collision chain for our element
            if (next == &row) {        // found it?
                *prev = next->ind_proc_next; // unlink (singly linked list)
                _db.ind_proc_n--;
                row.ind_proc_next = (lib_ams::FProc*)-1;// not-in-hash
                break;
            }
            prev = &next->ind_proc_next;
        }
    }
}

// --- lib_ams.FDb.ind_proc.Reserve
// Reserve enough room in the hash for N more elements. Return success code.
void lib_ams::ind_proc_Reserve(int n) {
    ind_proc_AbsReserve(_db.ind_proc_n + n);
}

// --- lib_ams.FDb.ind_proc.AbsReserve
// Reserve enough room for exacty N elements. Return success code.
void lib_ams::ind_proc_AbsReserve(int n) {
    u32 old_nbuckets = _db.ind_proc_buckets_n;
    u32 new_nelems   = n;
    // # of elements has to be roughly equal to the number of buckets
    if (new_nelems > old_nbuckets) {
        int new_nbuckets = i32_Max(algo::BumpToPow2(new_nelems), u32(4));
        u32 old_size = old_nbuckets * sizeof(lib_ams::FProc*);
        u32 new_size = new_nbuckets * sizeof(lib_ams::FProc*);
        // allocate new array. we don't use Realloc since copying is not needed and factor of 2 probably
        // means new memory will have to be allocated anyway
        lib_ams::FProc* *new_buckets = (lib_ams::FProc**)algo_lib::malloc_AllocMem(new_size);
        if (UNLIKELY(!new_buckets)) {
            FatalErrorExit("lib_ams.out_of_memory  field:lib_ams.FDb.ind_proc");
        }
        memset(new_buckets, 0, new_size); // clear pointers
        // rehash all entries
        for (int i = 0; i < _db.ind_proc_buckets_n; i++) {
            lib_ams::FProc* elem = _db.ind_proc_buckets_elems[i];
            while (elem) {
                lib_ams::FProc &row        = *elem;
                lib_ams::FProc* next       = row.ind_proc_next;
                u32 index          = row.ind_proc_hashval & (new_nbuckets-1);
                row.ind_proc_next     = new_buckets[index];
                new_buckets[index] = &row;
                elem               = next;
            }
        }
        // free old array
        algo_lib::malloc_FreeMem(_db.ind_proc_buckets_elems, old_size);
        _db.ind_proc_buckets_elems = new_buckets;
        _db.ind_proc_buckets_n = new_nbuckets;
    }
}

// --- lib_ams.FDb.grptype.Alloc
// Allocate memory for new default row.
// If out of memory, process is killed.
lib_ams::FGrptype& lib_ams::grptype_Alloc() {
    lib_ams::FGrptype* row = grptype_AllocMaybe();
    if (UNLIKELY(row == NULL)) {
        FatalErrorExit("lib_ams.out_of_mem  field:lib_ams.FDb.grptype  comment:'Alloc failed'");
    }
    return *row;
}

// --- lib_ams.FDb.grptype.AllocMaybe
// Allocate memory for new element. If out of memory, return NULL.
lib_ams::FGrptype* lib_ams::grptype_AllocMaybe() {
    lib_ams::FGrptype *row = (lib_ams::FGrptype*)grptype_AllocMem();
    if (row) {
        new (row) lib_ams::FGrptype; // call constructor
        ++lib_ams::_db.trace.alloc__db_grptype;
    }
    return row;
}

// --- lib_ams.FDb.grptype.InsertMaybe
// Create new row from struct.
// Return pointer to new element, or NULL if insertion failed (due to out-of-memory, duplicate key, etc)
lib_ams::FGrptype* lib_ams::grptype_InsertMaybe(const amsdb::Grptype &value) {
    lib_ams::FGrptype *row = &grptype_Alloc(); // if out of memory, process dies. if input error, return NULL.
    grptype_CopyIn(*row,const_cast<amsdb::Grptype&>(value));
    bool ok = grptype_XrefMaybe(*row); // this may return false
    if (!ok) {
        grptype_RemoveLast(); // delete offending row, any existing xrefs are cleared
        row = NULL; // forget this ever happened
    }
    return row;
}

// --- lib_ams.FDb.grptype.AllocMem
// Allocate space for one element. If no memory available, return NULL.
void* lib_ams::grptype_AllocMem() {
    u64 new_nelems     = _db.grptype_n+1;
    // compute level and index on level
    u64 bsr   = algo::u64_BitScanReverse(new_nelems);
    u64 base  = u64(1)<<bsr;
    u64 index = new_nelems-base;
    void *ret = NULL;
    // if level doesn't exist yet, create it
    lib_ams::FGrptype*  lev   = NULL;
    if (bsr < 36) {
        lev = _db.grptype_lary[bsr];
        if (!lev) {
            lev=(lib_ams::FGrptype*)algo_lib::malloc_AllocMem(sizeof(lib_ams::FGrptype) * (u64(1)<<bsr));
            _db.grptype_lary[bsr] = lev;
        }
    }
    // allocate element from this level
    if (lev) {
        _db.grptype_n = i64(new_nelems);
        ret = lev + index;
    }
    return ret;
}

// --- lib_ams.FDb.grptype.RemoveAll
// Remove all elements from Lary
void lib_ams::grptype_RemoveAll() {
    lib_ams::_db.trace.del__db_grptype += _db.grptype_n;
    for (u64 n = _db.grptype_n; n>0; ) {
        n--;
        grptype_qFind(u64(n)).~FGrptype(); // destroy last element
        _db.grptype_n = i64(n);
    }
}

// --- lib_ams.FDb.grptype.RemoveLast
// Delete last element of array. Do nothing if array is empty.
void lib_ams::grptype_RemoveLast() {
    u64 n = _db.grptype_n;
    if (n > 0) {
        n -= 1;
        grptype_qFind(u64(n)).~FGrptype();
        ++lib_ams::_db.trace.del__db_grptype;
        _db.grptype_n = i64(n);
    }
}

