// --- lib_ams.FShm..Uninit
void lib_ams::FShm_Uninit(lib_ams::FShm& parent) {
    shm_file_Cleanup(parent); // dmmeta.ffunc:lib_ams.FShm.shm_file/Cleanup
    c_shm_stdout_Remove(parent); // remove shm from index c_shm_stdout
    c_shm_stdin_Remove(parent); // remove shm from index c_shm_stdin
    ind_shm_Remove(parent); // remove shm from index ind_shm
    cd_poll_read_Remove(parent); // remove shm from index cd_poll_read
    lib_ams::FProc* p_proc_id = lib_ams::ind_proc_Find(parent.grp_id.proc_id);
    if (p_proc_id)  {
        c_shm_Remove(*p_proc_id, parent);// remove shm from index c_shm
    }
    c_cur_shm_Remove(parent); // remove shm from index c_cur_shm
    zd_park_read_Remove(parent); // remove shm from index zd_park_read
    zd_outshm_Remove(parent); // remove shm from index zd_outshm
    zd_wake_Remove(parent); // remove shm from index zd_wake

    // lib_ams.FShm.chunkref.Uninit (Tary)  //Chunks this lane's readers may still be reading, at most board_max_chunkref
    // remove all elements from lib_ams.FShm.chunkref
    chunkref_RemoveAll(parent);
    // free memory for Tary lib_ams.FShm.chunkref
    algo_lib::malloc_FreeMem(parent.chunkref_elems, sizeof(lib_ams::Chunkref)*parent.chunkref_max); // (lib_ams.FShm.chunkref)

    // lib_ams.FShm.c_lane.Uninit (Ptrary)  //Lanes holding a pin on a chunk of this board, board only
    algo_lib::malloc_FreeMem(parent.c_lane_elems, sizeof(lib_ams::FShm*)*parent.c_lane_max); // (lib_ams.FShm.c_lane)

    // lib_ams.FShm.c_chunk.Uninit (Ptrary)  //Chunks of this board in offset order, board only
    algo_lib::malloc_FreeMem(parent.c_chunk_elems, sizeof(lib_ams::FChunk*)*parent.c_chunk_max); // (lib_ams.FShm.c_chunk)
}

// --- lib_ams.FieldId.value.ToCstr
// Convert numeric value of field to one of predefined string constants.
// If string is found, return a static C string. Otherwise, return NULL.
const char* lib_ams::value_ToCstr(const lib_ams::FieldId& parent) {
    const char *ret = NULL;
    switch(value_GetEnum(parent)) {
        case lib_ams_FieldId_value         : ret = "value";  break;
    }
    return ret;
}

// --- lib_ams.FieldId.value.Print
// Convert value to a string. First, attempt conversion to a known string.
// If no string matches, print value as a numeric value.
void lib_ams::value_Print(const lib_ams::FieldId& parent, algo::cstring &lhs) {
    const char *strval = value_ToCstr(parent);
    if (strval) {
        lhs << strval;
    } else {
        lhs << parent.value;
    }
}

// --- lib_ams.FieldId.value.SetStrptrMaybe
// Convert string to field.
// If the string is invalid, do not modify field and return false.
// In case of success, return true
bool lib_ams::value_SetStrptrMaybe(lib_ams::FieldId& parent, algo::strptr rhs) {
    bool ret = false;
    switch (elems_N(rhs)) {
        case 5: {
            switch (u64(algo::ReadLE32(rhs.elems))|(u64(rhs[4])<<32)) {
                case LE_STR5('v','a','l','u','e'): {
                    value_SetEnum(parent,lib_ams_FieldId_value); ret = true; break;
                }
            }
            break;
        }
    }
    return ret;
}

// --- lib_ams.FieldId.value.SetStrptr
// Convert string to field.
// If the string is invalid, set numeric value to DFLT
void lib_ams::value_SetStrptr(lib_ams::FieldId& parent, algo::strptr rhs, lib_ams_FieldIdEnum dflt) {
    if (!value_SetStrptrMaybe(parent,rhs)) value_SetEnum(parent,dflt);
}

// --- lib_ams.FieldId.value.ReadStrptrMaybe
// Convert string to field. Return success value
bool lib_ams::value_ReadStrptrMaybe(lib_ams::FieldId& parent, algo::strptr rhs) {
    bool retval = false;
    retval = value_SetStrptrMaybe(parent,rhs); // try symbol conversion
    if (!retval) { // didn't work? try reading as underlying type
        retval = i32_ReadStrptrMaybe(parent.value,rhs);
    }
    return retval;
}

// --- lib_ams.FieldId..ReadStrptrMaybe
// Read fields of lib_ams::FieldId from an ascii string.
// The format of the string is the format of the lib_ams::FieldId's only field
bool lib_ams::FieldId_ReadStrptrMaybe(lib_ams::FieldId &parent, algo::strptr in_str) {
    bool retval = true;
    retval = retval && value_ReadStrptrMaybe(parent, in_str);
    return retval;
}

// --- lib_ams.FieldId..Print
// print string representation of ROW to string STR
// cfmt:lib_ams.FieldId.String  printfmt:Raw
void lib_ams::FieldId_Print(lib_ams::FieldId row, algo::cstring& str) {
    lib_ams::value_Print(row, str);
}

// --- lib_ams...SizeCheck
inline static void lib_ams::SizeCheck() {
}

// --- lib_ams...StaticCheck
void lib_ams::StaticCheck() {
    algo_assert(sizeof(lib_ams::_db_h_amsmsg_hook) == 8); // csize:lib_ams._db_h_amsmsg_hook
    algo_assert(sizeof(lib_ams::_db_h_sigchld_hook) == 8); // csize:lib_ams._db_h_sigchld_hook
    algo_assert(sizeof(lib_ams::_db_h_terminate_hook) == 8); // csize:lib_ams._db_h_terminate_hook
    algo_assert(sizeof(lib_ams::shm_h_amsmsg_hook) == 8); // csize:lib_ams.shm_h_amsmsg_hook
    algo_assert(_offset_of(lib_ams::trace, del__db_proctype) + sizeof(((lib_ams::trace*)0)->del__db_proctype) == sizeof(lib_ams::trace));
    algo_assert(_offset_of(lib_ams::FieldId, value) + sizeof(((lib_ams::FieldId*)0)->value) == sizeof(lib_ams::FieldId));
}

// --- lib_ams...InputLineMsg_FmtByteAry
// Construct a new ams::InputLineMsg in the space provided by BUF.
// A total beyond the i32 frame length domain constructs nothing and returns NULL.
ams::InputLineMsg * lib_ams::InputLineMsg_FmtByteAry(algo::ByteAry &buf, ams::ProcId proc_id, algo::aryptr<char > payload) {
    ams::InputLineMsg  *msg = NULL;
    size_t len = sizeof(ams::InputLineMsg);
    u64 payload_ary_len = u64(elems_N(payload)) * sizeof(char);
    len += payload_ary_len;
    if (len > 0x7fffffff) {
        return NULL; // a frame length is an i32, and so is every buffer size argument
    }
    ary_RemoveAll(buf);
    msg = (ams::InputLineMsg*)ary_AllocN(buf,len).elems;
    msg->type = u32(22);
    msg->length = u32(len);
    msg->proc_id = proc_id;
    memcpy(payload_Addr(*msg), payload.elems, payload_ary_len);
    return msg;
}

// --- lib_ams...LogMsg_FmtAlloc
// Construct a new ams::LogMsg in the space provided by ALLOC.
// If ALLOC cannot provide the space, construct nothing and return NULL.
// A total beyond the i32 frame length domain constructs nothing and returns NULL.
ams::LogMsg * lib_ams::LogMsg_FmtAlloc(const algo::Alloc &alloc, ams::ProcId proc_id, algo::SchedTime tstamp, algo::aryptr<char > logcat, algo::aryptr<char > text) {
    ams::LogMsg  *msg = NULL;
    size_t len = sizeof(ams::LogMsg);
    u64 logcat_ary_len = u64(elems_N(logcat)) * sizeof(char);
    len += logcat_ary_len;
    u64 text_ary_len = u64(elems_N(text)) * sizeof(char);
    len += text_ary_len;
    if (len > 0x7fffffff) {
        return NULL; // a frame length is an i32, and so is every buffer size argument
    }
    msg = (ams::LogMsg*)alloc.begin(alloc.ctx, int(len));
    if (!msg) {
        return NULL; // no room.
    }
    msg->type = u32(6);
    msg->length = u32(len);
    msg->proc_id = proc_id;
    msg->tstamp = tstamp;
    memcpy(logcat_Addr(*msg), logcat.elems, logcat_ary_len);
    (*msg).logcat_end = u32(logcat_ary_len);
    memcpy(text_Addr(*msg), text.elems, text_ary_len);
    if (alloc.end) {
        alloc.end(alloc.ctx, msg, int(len)); // finalize
    }
    return msg;
}

